mapper.update:
UPDATE ICOMBOARD_NOTICE SET SUBJECT = #{SUBJECT}, CONTEXT = #{CONTEXT}, IMAGE_KEY = #{IMAGE_KEY}, FROM_DATE = REPLACE(#{FROM_DATE}, '/', ''), TO_DATE = REPLACE(#{TO_DATE}, '/', ''), IMPORTANT_FLAG = NVL(#{IMPORTANT_FLAG}, 'N'), ALWAYS_SHOW_FLAG = NVL(#{ALWAYS_SHOW_FLAG}, 'N'), EXPOSE_TARGET = NVL(#{EXPOSE_TARGET}, 'ALL'), NOTICE_TYPE = NVL(#{NOTICE_TYPE}, 'CMN'), ALL_CUSTOMER_FLAG = NVL(#{ALL_CUSTOMER_FLAG}, 'N')
, OPEN_FLAG = #{OPEN_FLAG}
WHERE BID = #{BID} AND BTYPE = #{BTYPE}

mapper.delete:

DELETE ICOMBOARD_NOTICE_DT
WHERE BID = #{BID}
  AND BTYPE = #{BTYPE}

mapper.update:

UPDATE ICOMBOARD_NOTICE_DT
SET STATUS = 'D'
WHERE BID = #{BID}
  AND BTYPE = #{BTYPE}


UPDATE ICOMBOARD_NOTICE
SET STATUS = 'D'
	, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
	, CHANGE_USER_ID = #{USER_ID}
WHERE BID = #{BID}
  AND BTYPE = #{BTYPE}


UPDATE ICOMBOARD_NOTICE
SET OPEN_FLAG = #{OPEN_FLAG}
WHERE BID = #{BID}
  AND BTYPE = #{BTYPE}


UPDATE ICOMBOARD_NOTICE
SET LCOUNT = NVL(LCOUNT, 0) + 1
WHERE BID = #{BID}
  AND BTYPE = #{BTYPE}
